INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (451, 1, 'mkswap 역할', 'mkswap 은 무엇을 할까요?', '영역을 만들어요.', NULL, NULL, '[]', 'choice', '["스왑 영역을 사용 상태로 바꾼다", "스왑 영역의 사용량을 보여 준다", "장치나 파일에 리눅스 스왑 영역을 설정한다", "스왑 영역을 삭제하고 해제한다"]', 2, 'mkswap 문서는 장치나 파일에 리눅스 스왑 영역을 설정하며, 만든 뒤에 swapon 으로 사용을 시작해야 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 2, 'swapon 필요', '`mkswap` 으로 스왑 영역을 만든 직후 상태는 어떨까요?', '아직 안 켜졌어요.', NULL, NULL, '[]', 'choice', '["만들자마자 자동으로 쓰이기 시작한다", "`swapon` 으로 켜야 실제로 쓰인다", "재부팅해야만 쓰이기 시작한다", "fstab 에 쓰면 이미 쓰이고 있다"]', 1, '문서는 스왑 영역을 만든 뒤 swapon(8) 으로 사용을 시작해야 하며, 보통 /etc/fstab 에 적어 부팅 때 swapon -a 로 쓰게 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 3, 'blocks 인자', 'mkswap 의 마지막 **blocks 인자** 에 대해 문서는 어떻게 말할까요?', '불필요하고 위험해요.', NULL, NULL, '[]', 'choice', '["불필요하고 오타 시 위험해 비권장이다", "크기를 꼭 적어야 하는 필수 인자이다", "메가바이트 단위로 크기를 정한다", "생략하면 최소 크기로 만들어진다"]', 0, '문서는 blocks 가 하위 호환을 위해 남은 불필요한 인자이고, 생략하면 파티션이나 파일 전체를 쓰며, 적으면 오타가 디스크를 망가뜨릴 수 있어 현명하지 않다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 4, '첫 블록', 'mkswap 은 대상의 **첫 블록** 을 어떻게 다룰까요?', 'mkfs 계열처럼요.', NULL, NULL, '[]', 'choice', '["스왑 헤더가 첫 블록을 덮어써서 부트로더를 보존한다", "첫 블록은 절대 건드리지 않는다", "첫 블록을 지우기 전에 항상 백업한다", "지우되 디스크 레이블이 있으면 거부한다"]', 3, '문서는 mkswap 이 다른 mkfs 류처럼 첫 파티션 블록을 지워 이전 파일시스템을 보이지 않게 하되, 디스크 레이블(SUN, BSD 등)이 있는 장치의 첫 블록은 지우기를 거부한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 5, '권장 구성', '문서가 권하는 **스왑 영역 구성** 은 무엇일까요?', '따로 둬요.', NULL, NULL, '[]', 'choice', '["부트로더와 같은 첫 블록 영역을 함께 쓴다", "루트 파일시스템 안의 파일로만 쓴다", "별도의 파티션을 스왑 전용으로 쓴다", "디스크 레이블과 같은 위치에 둔다"]', 2, '문서는 스왑 헤더가 첫 블록을 건드리지 않아 부트로더나 디스크 레이블이 있을 수 있지만 권장하지 않으며, 별도 파티션을 쓰는 것이 권장 구성이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 6, '-L 옵션', '`mkswap -L swap0 /dev/sdb2` 의 **-L** 은 무엇을 위한 것일까요?', '이름이에요.', NULL, NULL, '[]', 'choice', '["스왑 영역의 최대 크기를 제한한다", "레이블을 정해 swapon 에 쓴다", "스왑 영역에 잠금을 건다", "스왑 영역의 우선순위를 정한다"]', 1, '문서는 -L 이 레이블을 지정해 swapon(8) 을 레이블로 사용할 수 있게 한다고 설명합니다. 잠금은 --lock 입니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 7, '-F 옵션', '`mkswap -F --size 1G` 같은 **파일 방식** 에서 -F 는 무엇을 할까요?', '파일을 준비해요.', NULL, NULL, '[]', 'choice', '["스왑 파일을 만들고 채운다", "기존 파일을 지우고 장치로 바꾼다", "스왑 영역을 강제로 확장한다", "파일을 압축해서 스왑으로 쓴다"]', 0, '문서는 -F/--file 이 적절한 파일 권한으로 스왑 파일을 만들고 디스크에 블록을 채운다고 설명하며, --size 는 --file 과 함께 쓸 때만 의미가 있다고 합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 8, '-f 옵션', '`mkswap -f` 는 무엇을 허용할까요?', '강제예요.', NULL, NULL, '[]', 'choice', '["잘못된 UUID 형식을 자동으로 고친다", "이미 사용 중인 스왑을 자동으로 끈다", "불량 블록 검사를 건너뛰게 한다", "대상보다 큰 영역 생성을 허용한다"]', 3, '문서는 -f/--force 가 바보 같은 동작도 진행해 대상보다 큰 스왑 영역 생성을 허용하고, 이 옵션이 없으면 파티션 테이블이 있는 장치의 첫 블록 삭제를 거부한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 9, '-c 옵션', '`mkswap -c` 는 무엇을 할까요?', '검사예요.', NULL, NULL, '[]', 'choice', '["스왑을 만든 뒤 사용량을 계속 점검한다", "스왑 영역의 내용을 압축해서 저장한다", "만들기 전에 불량 블록을 검사한다", "스왑 영역의 복사본을 하나 더 만든다"]', 2, '문서는 -c/--check 가 블록 장치에서 스왑 영역을 만들기 전에 불량 블록을 검사하고, 발견하면 개수를 출력한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 10, '스왑 만들기', '장치에 **스왑 영역을 만드는** 명령입니다. 빈칸을 채우세요.', '스왑 영역을 만든다는 뜻이에요.', NULL, NULL, '[]', 'fill', '["mkswap", "swapon", "swapoff", "mkfs"]', NULL, 'mkswap 은 스왑 영역을 만들고, swapon 은 켜고, swapoff 는 끕니다.', '[0]', '{0} -L swap0 /dev/sdb2', NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 11, '파일 스왑', '스왑 **파일** 의 크기를 정하는 옵션입니다. 빈칸을 채우세요.', 'size 의 s 예요.', NULL, NULL, '[]', 'fill', '["--size", "--label", "--uuid", "--offset"]', NULL, '--size 는 만들 스왑 파일의 크기를 정하며 --file 과 함께 쓸 때만 의미가 있습니다.', '[0]', 'mkswap -F {0} 1G swapfile', NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]'),
  (451, 12, '스왑 설정', '스왑 영역을 새로 쓰기 시작하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 켜기 → 영구화 → 확인이에요.', NULL, NULL, '[]', 'order', '["`mkswap` 으로 스왑 영역을 만든다", "`swapon` 으로 스왑을 켠다", "/etc/fstab 에 swap 항목을 추가한다", "`swapon --show` 로 켜진 스왑을 확인한다"]', NULL, '문서의 mkswap 후 swapon 필요, fstab 에 적어 부팅 때 swapon -a 로 쓴다는 설명과 --show 를 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "mkswap(8) man page", "url": "https://man7.org/linux/man-pages/man8/mkswap.8.html"}]');
